import { Mesh, PlaneGeometry, MeshBasicNodeMaterial, Group } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep, uniform, float, fract, hash } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const group = new Group();
  group.name = 'features-card-2-label';

  const sourceRect = config.atlasRegion?.sourceRect ?? { x: 0, y: 0, width: 512, height: 320 };
  const atlasDims = { w: 512, h: 320 };

  const uRect = uniform(vec3(sourceRect.x, sourceRect.y, 0));
  const uDims = uniform(vec3(atlasDims.w, atlasDims.h, 0));

  const rectUV = uv().mul(uDims.xy).sub(uRect.xy).div(uDims.xy);
  const flippedY = vec3(rectUV.x, float(1.0).sub(rectUV.y), 0);
  const img = texture(config.imageUrl, flippedY);

  const planeMat = new MeshBasicNodeMaterial();
  planeMat.transparent = true;
  planeMat.opacityNode = img.x;

  const plane = new Mesh(new PlaneGeometry(1, 0.625), planeMat);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // Overlay grid backing (static composition)
  const overlayMat = new MeshBasicNodeMaterial();
  const og = new Mesh(new PlaneGeometry(1, 0.625), overlayMat);
  group.add(og);

  // Text content
  const fontAtlas = ctx.fontAtlas;
  items.forEach((item) => {
    const txt = fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
      letterSpacingPx: 0.5,
    });
    txt.position.set(-0.3, 0.1, 0.01);
    group.add(txt);
  });

  const timelines = [];
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    planeMat.dispose();
    plane.geometry.dispose();
    overlayMat.dispose();
    og.geometry.dispose();
  };

  return group;
}
